package net.tecnihardcore;
import net.fabricmc.fabric.api.networking.v1.*;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.Identifier;import java.nio.file.*;import java.util.*;
final class BossWaypoints{static final Identifier SYNC=Hardcore.id("boss_waypoints_v1");static void initServer(){ServerPlayConnectionEvents.JOIN.register((h,s,server)->server.execute(()->send(h.player)));}static void send(ServerPlayerEntity p){if(!ServerPlayNetworking.canSend(p,SYNC))return;var b=PacketByteBufs.create();b.writeVarInt(3);String[] n={"Custodio Norte","Custodio Sur","Custodio Oeste"};int[] x={0,0,-8000},z={-8000,8000,0};for(int i=0;i<3;i++){b.writeString(n[i],32);b.writeInt(x[i]);b.writeInt(96);b.writeInt(z[i]);}ServerPlayNetworking.send(p,SYNC,b);}static void initClient(){ClientPlayNetworking.registerGlobalReceiver(SYNC,(c,h,b,r)->{int n=b.readVarInt();var lines=new ArrayList<String>();for(int i=0;i<n;i++){String name=b.readString(32);int x=b.readInt(),y=b.readInt(),z=b.readInt();lines.add("waypoint:"+name+":"+name.substring(9,11).toUpperCase(Locale.ROOT)+":"+x+":"+y+":"+z+":5:false:0:0");}c.execute(()->{try{Path root=c.runDirectory.toPath().resolve("XaeroWaypoints");Files.createDirectories(root);String a=c.getCurrentServerEntry()!=null?c.getCurrentServerEntry().address:"TecniHardcore";Path f=root.resolve("Multiplayer_"+a.replaceAll("[^A-Za-z0-9._-]","_")).resolve("dim%0.txt");Files.createDirectories(f.getParent());String old=Files.exists(f)?Files.readString(f):"";StringBuilder out=new StringBuilder();for(String l:old.split("\\R"))if(!l.startsWith("waypoint:Custodio ")&&!l.isBlank())out.append(l).append('\n');for(String l:lines)out.append(l).append('\n');Files.writeString(f,out.toString());}catch(Exception e){Hardcore.LOG.warn("No se pudieron sincronizar waypoints",e);}});});}}
